 if(sit){this.ellipse(-13,-8,18,9,p.color);this.ellipse(13,-8,18,9,p.color);this.path([[-17,-39],[17,-39],[24,-12],[-24,-12]],p.color);this.line(-15,-27,-20,-13,'#efbd87',7);this.line(15,-27,20,-13,'#efbd87',7);}else{this.ellipse(-10,-7+walk*3,8,5,'#694f3d');this.ellipse(10,-7-walk*3,8,5,'#694f3d');}
