 const headY=sit?-52:bow?-54:-60;this.ellipse(0,headY,23,25,'#f4cd9d');this.ellipse(-7,headY-12,12,8,'#ffdfb1');this.line(-10,headY,-6,headY+(sit?1:0),'#665440',2.5);this.line(7,headY,11,headY+(sit?1:0),'#665440',2.5);this.ellipse(-15,headY+7,4,2,'#eda484');this.ellipse(15,headY+7,4,2,'#eda484');this.line(-3,headY+9,3,headY+9,'#b18361',2);this.outfit(p,bow,false);
