 if(action==='fish'){const sway=Math.sin(t*3)*6;this.line(15,-35,31,-20+sway,'#efbd87',8);this.rounded(20,-23+sway,28,15,5,'#ba8047');this.ellipse(34,-23+sway,14,5,'#efd4a0');}
 if(action==='chant'){const beat=Math.max(0,1-age/.5);this.line(15,-35,27,-29-beat*20,'#efbd87',8);this.line(27,-29-beat*20,38,-42-beat*20,'#82613d',4);this.line(-15,-35,-7,-27,'#efbd87',8);}
 if(action==='beads'){const a=t*2;this.line(-15,-35,-6,-26,'#efbd87',7);this.line(15,-35,7+Math.sin(a)*3,-26,'#efbd87',7);for(let i=0;i<10;i++)this.ellipse(Math.cos(i*Math.PI/5+a)*12,-24+Math.sin(i*Math.PI/5+a)*8,2.6,2.6,'#805832');}
